[Test]
procedure PublicHelp_NamesNoIssueNumberNoInternalObjectNoProcedure()
var
    ContractMgt: Codeunit "Msg Contract Mgt ori";
    Regex: Codeunit Regex;
    MessageType: Enum "Message Type ori";
    Contract: JsonObject;
    ContractText: Text;
    TypeName: Text;
    Forbidden: List of [Text];
    Term: Text;
    Ordinal: Integer;
    Checked: Integer;
begin
    // [SCENARIO] #480 AC-01, AC-04: the contract of every Help, User, Email, Session, Webhook and Bifrost type has no issue number,
    // no number of an internal object, no internal table name, no AL procedure name and no other product.
    Initialize();
    Forbidden.Add('AssertIsLicensed');
    Forbidden.Add('ExecuteBifrostTask');
    Forbidden.Add('Orchestrator');
    Forbidden.Add('Omit Commit');
    Forbidden.Add('Dispatcher');
    Forbidden.Add('Note ori');
    Forbidden.Add('Webhook Access ori');
    Forbidden.Add('Message Task ori');
    Forbidden.Add('Message Argument ori');

    foreach Ordinal in Enum::"Message Type ori".Ordinals() do begin
        MessageType := Enum::"Message Type ori".FromInteger(Ordinal);
        TypeName := Enum::"Message Type ori".Names().Get(Enum::"Message Type ori".Ordinals().IndexOf(Ordinal));
        if IsPublicNamespace(TypeName) then
            if ContractMgt.GetContract(MessageType, Contract) then begin
                Contract.WriteTo(ContractText);
                Checked += 1;
                Assert.IsFalse(Regex.IsMatch(ContractText, '#[0-9]'), TypeName + ' names an issue number');
                Assert.IsFalse(Regex.IsMatch(ContractText, '1007[78][0-9]{3}'), TypeName + ' names the number of an internal object');
                foreach Term in Forbidden do
                    Assert.IsFalse(ContractText.Contains(Term), TypeName + ' names "' + Term + '"');
            end;
    end;
    Assert.IsTrue(Checked > 20, 'The guard checked the contracts of the public namespaces');
end;
